// Compute ISO week filename using Intl.DateTimeFormat (spec-compliant, ISO 8601 compliant)
const now = new Date();
const weekNum = parseInt(
  new Intl.DateTimeFormat('en', { weekYear: 'numeric', week: 'numeric' })
    .formatToParts(now)
    .find(p => p.type === 'week').value,
  10
);
const year = parseInt(
  new Intl.DateTimeFormat('en', { weekYear: 'numeric', week: 'numeric' })
    .formatToParts(now)
    .find(p => p.type === 'weekYear').value,
  10
);
const weekStr = String(weekNum).padStart(2, '0');
const isoWeek = `${year}-W${weekStr}`;
const filename = `weekly-${isoWeek}.md`;

const digestContent = $json.stdout || $json.output || '';
const exitCode = $json.exitCode || 0;

if (exitCode !== 0) {
  return [{ json: {
    success: false,
    error: $json.stderr || 'digest generation failed',
    filename
  }}];
}

return [{ json: { success: true, content: digestContent, filename, isoWeek } }];

// Write digest to wiki via stdin pipe (no heredoc — avoids shell injection in content)
const content = $('Prepare Digest File').first().json.content;
const filename = $('Prepare Digest File').first().json.filename;
const wikiDir = process.env.WIKI_SYNC_DIR || '/files/wiki';
const fullPath = `${wikiDir}/devrel/insights/${filename}`;
const b64 = Buffer.from(content, 'utf8').toString('base64');

return [{ json: {
  write_command: `mkdir -p '${wikiDir}/devrel/insights' && echo '${b64}' | base64 -d > '${fullPath}'`,
  fullPath,
  filename
} }];

